descriptor.templateCss:
.dg-trend-card {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #f59e0b;
  padding: 16px 20px 12px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.card-header-dg {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.title-dg {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.icon-dg { font-size: 16px; }
.badge-dg {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
}
.badge-dg.ok {
  color: #64B856;
  border: 1.5px solid #64B856;
  background: rgba(100, 184, 86, 0.1);
}
.badge-dg.warn {
  color: #f59e0b;
  border: 1.5px solid #f59e0b;
  background: rgba(245, 158, 11, 0.1);
}
.phases-kpi-bar {
  display: flex;
  justify-content: space-around;
  align-items: center;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(100, 184, 86, 0.12);
  border-radius: 8px;
  padding: 6px 12px;
  margin: 6px 0;
}
.phase-item {
  display: flex;
  align-items: baseline;
  gap: 6px;
}
.p-tag { font-size: 10px; font-weight: 700; }
.phase-u .p-tag { color: #eab308; }
.phase-v .p-tag { color: #38bdf8; }
.phase-w .p-tag { color: #ef4444; }
.p-val { font-size: 20px; font-weight: 800; color: #f1f5f9; line-height: 1; }
.p-unit { font-size: 11px; color: #94a3b8; font-weight: 600; }
.sep-kpi { width: 1px; height: 22px; background: rgba(148, 163, 184, 0.15); }
.chart-container-dg {
  width: 100%;
  flex: 1;
  min-height: 95px;
  position: relative;
}
.chart-container-dg canvas {
  width: 100%;
  height: 100%;
  display: block;
}
.card-footer-dg {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 6px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() {
  self.ctx.$scope.drawChart = self.drawChart;
  self.onDataUpdated();
};
self.onResize = function() { self.drawChart(); };

self.drawChart = function() {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container) return;
  var canvas = container.querySelector('#chart-dg-currents');
  if (!canvas) return;

  var rect = canvas.getBoundingClientRect();
  var dpr = window.devicePixelRatio || 1;
  var w = rect.width || 400;
  var h = rect.height || 100;
  canvas.width = w * dpr;
  canvas.height = h * dpr;
  var ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, w, h);

  var uData = self.uSeries || [];
  var vData = self.vSeries || [];
  var wData = self.wSeries || [];

  // Generador de prueba si aún no hay telemetría en vivo
  if (uData.length < 2) {
    uData = []; vData = []; wData = [];
    var now = Date.now();
    for (var k = 20; k >= 0; k--) {
      var t = now - k * 60000;
      uData.push([t, 125 + Math.sin(k * 0.4) * 8]);
      vData.push([t, 123 + Math.cos(k * 0.4) * 7]);
      wData.push([t, 124 + Math.sin(k * 0.3) * 6]);
    }
  }

  var padL = 32, padR = 15, padT = 10, padB = 18;
  var plotW = w - padL - padR;
  var plotH = h - padT - padB;
  if (plotW <= 10 || plotH <= 10) return;

  var maxI = 250, minI = 0;

  // Rejilla de fondo
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
  ctx.lineWidth = 1;
  for (var r = 0; r <= 2; r++) {
    var y = padT + (plotH / 2) * r;
    ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(w - padR, y); ctx.stroke();
  }

  ctx.font = '10px -apple-system, sans-serif';
  ctx.fillStyle = '#64748b';
  ctx.textAlign = 'right';
  ctx.fillText(maxI + 'A', padL - 6, padT + 8);
  ctx.fillText('0A', padL - 6, h - padB);

  var n = uData.length;
  var getX = function(idx) { return padL + (idx / (n - 1)) * plotW; };
  var getY = function(val) {
    var ratio = Math.max(0, Math.min(1, (val - minI) / (maxI - minI)));
    return padT + plotH * (1 - ratio);
  };

  var drawPhaseLine = function(series, color) {
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    for (var i = 0; i < n; i++) {
      var x = getX(i);
      var y = getY(series[i][1]);
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  };

  drawPhaseLine(uData, '#eab308');
  drawPhaseLine(vData, '#38bdf8');
  drawPhaseLine(wData, '#ef4444');
};

self.onDataUpdated = function() {
  var data = self.ctx.data;
  var iu = 0.0, iv = 0.0, iw = 0.0;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      var k = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
      if (item.data && item.data.length > 0) {
        var lastPt = parseFloat(item.data[item.data.length - 1][1]);
        if (!isNaN(lastPt)) {
          if (k.indexOf('fase_u') !== -1 || i === 0) { iu = lastPt; self.uSeries = item.data; }
          else if (k.indexOf('fase_v') !== -1 || i === 1) { iv = lastPt; self.vSeries = item.data; }
          else if (k.indexOf('fase_w') !== -1 || i === 2) { iw = lastPt; self.wSeries = item.data; }
        }
      }
    }
  }

  var avg = (iu + iv + iw) / 3;
  var maxDiff = Math.max(Math.abs(iu - avg), Math.abs(iv - avg), Math.abs(iw - avg));
  var unbalancePct = avg > 1 ? (maxDiff / avg) * 100 : 0;
  var isOk = unbalancePct < 5.0;

  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var elU = container.querySelector('#iu-val');
    var elV = container.querySelector('#iv-val');
    var elW = container.querySelector('#iw-val');
    if (elU) elU.textContent = iu.toFixed(1);
    if (elV) elV.textContent = iv.toFixed(1);
    if (elW) elW.textContent = iw.toFixed(1);

    var elAvg = container.querySelector('#i-avg-text');
    if (elAvg) elAvg.textContent = avg.toFixed(1) + ' A';

    var elBadge = container.querySelector('#current-unbalance-badge');
    if (elBadge) {
      if (avg < 1) {
        elBadge.textContent = 'SIN CARGA (0.0 A)';
        elBadge.className = 'badge-dg ok';
      } else {
        elBadge.textContent = isOk ? 'BALANCEADO (Δ ' + unbalancePct.toFixed(1) + '%)' : 'DESBALANCE (Δ ' + unbalancePct.toFixed(1) + '%)';
        elBadge.className = 'badge-dg ' + (isOk ? 'ok' : 'warn');
      }
    }
  }
  self.drawChart();
};
self.onDestroy = function() {};
